def tenumerate(iterable, start=0, total=None, tqdm_class=tqdm_auto, **tqdm_kwargs):
    """
    Equivalent of `numpy.ndenumerate` or builtin `enumerate`.

    Parameters
    ----------
    tqdm_class  : [default: tqdm.auto.tqdm].
    """
    try:
        import numpy as np
    except ImportError:
        pass
    else:
        if isinstance(iterable, np.ndarray):
            return tqdm_class(np.ndenumerate(iterable), total=total or len(iterable), **tqdm_kwargs)
    # Set 'start' as the prefix in tqdm_class to avoid messing up the progress bar output
    tqdm_kwargs['desc'] = str(start)
    return enumerate(tqdm_class(iterable, **tqdm_kwargs))
